mapper.update:
UPDATE gw_biz_contract
   SET status_cd = 'TERMINATED', terminated_at = CURRENT_TIMESTAMP,
       termination_reason = #{reason}
 WHERE biz_contract_id = #{bizContractId}

mapper.select:
SELECT FROM gw_biz_contract c JOIN gw_vendor v ON v.vendor_id = c.vendor_id LEFT JOIN gw_user u ON u.user_id = c.owner_user_id LEFT JOIN gw_dept d ON d.dept_id = c.dept_id WHERE c.deleted_at IS NULL
AND (LOWER(c.title) LIKE LOWER('%' || #{keyword} || '%') OR LOWER(c.contract_no) LIKE LOWER('%' || #{keyword} || '%') OR LOWER(v.company_nm) LIKE LOWER('%' || #{keyword} || '%'))
AND c.status_cd = #{statusCd} AND c.vendor_id = #{vendorId} ORDER BY c.start_dt DESC, c.biz_contract_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM gw_biz_contract c JOIN gw_vendor v ON v.vendor_id = c.vendor_id WHERE c.deleted_at IS NULL
AND (LOWER(c.title) LIKE LOWER('%' || #{keyword} || '%') OR LOWER(c.contract_no) LIKE LOWER('%' || #{keyword} || '%') OR LOWER(v.company_nm) LIKE LOWER('%' || #{keyword} || '%'))
AND c.status_cd = #{statusCd} AND c.vendor_id = #{vendorId}

